INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (108, 'hotPreenchStatusCards', 'Status cards do gestor no ciclo.', 'SQL', 'SELECT os.*, cr.CODIGO as CR_CODIGO, cr.NOME as CR_NOME
     FROM ORCAMENTO_STATUS os JOIN CENTRO_RESULTADO cr ON cr.ID = os.CR_ID
     WHERE os.CICLO_ID = {{cicloId}} AND os.GESTOR_ID = {{gestorId}} ORDER BY cr.CODIGO', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
